import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"5、【需】 乾下坎上","description":"周易尚氏學 - 5、【需】 乾下坎上","frontmatter":{"title":"5、【需】 乾下坎上","description":"周易尚氏學 - 5、【需】 乾下坎上"},"headers":[],"relativePath":"classics/shangshi/010.md","filePath":"classics/shangshi/010.md"}'),s={name:"classics/shangshi/010.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_5、【需】-乾下坎上" tabindex="-1">5、【需】 乾下坎上 <a class="header-anchor" href="#_5、【需】-乾下坎上" aria-label="Permalink to “5、【需】 乾下坎上”">​</a></h1><p>乾為行。行而遇險。故曰需。需待也。歸藏作溽。坎兌皆水。故溽。溽溼也。而溽與濡音義並同。楊氏古音雲。溽人餘切。歸藏易。需卦作溽。同濡。案孟子。是何濡滯也。是溽有遲義。古文多省筆。疑需為古文濡字。與歸藏同。且濡滯亦有須義。與彖傳不背。周易本因二易而作。溽濡需不過字形之輾轉耳。音義並同也。卦辭皆指九五。五上下皆陰。故有孚。互離故光。得位放亨。貞吉者。卜問則吉也。坤為水。為大川。易林賁之損雲。龍蛇所聚。大水來處。以損互震為龍蛇。互坤為水。又師之復。淵泉堤防。水道利通。亦以復坤為泉為水。此外九家。說蠱之利涉大川雲。此卦乾天有河。坤地有水。二爻升降。出入乾坤。利涉大大川也。亦以坤為大川。利涉謂五。言五居坤中。孚於上下而利也。故彖傳以位乎天位。往有功釋之。而虞翻謂往指二。二失位。變陰涉坎。故利涉。夫以坎為大川。涉之而利。則不必需矣。是背卦義也。彼夫蹇無坤也。而曰利西南。以蹇五居坤中也。需五亦居坤中。坤為大川。當位而尊。上下皆孚。故曰往有功。五居外。故曰往。非必內卦往外卦。方謂往也。此卦只五爻能利涉。他爻無利者。自坤水象失傳。不知五所涉者為坤水。為大川。必以坎為大川。於是易之利涉大川。無一得解者。</p><p>彖曰。需。須也。險在前也。剛健而不陷。其義不困窮矣。需有孚光亨貞吉。位乎天位。以正中也。利涉大川。往有功也。</p><p>須待也。待則不陷於險中。故不困窮。釋需之故也。位乎天位。往有功。皆謂九五。謂九五居坤水之中。上下皆孚。有功即利涉。虞翻以二當之。失彖傳旨矣。</p><p>象曰。雲上於天。需。君子以飲食宴樂。</p><p>坎為雲。故曰云上於天。二四兌。兌口。故曰飲食。兌悅。故曰宴樂。乾為君子。言君子飲食宴樂。從容以俟也。</p><p>初九。需於郊。利用恆。無咎。</p><p>乾為郊。初臨重陽。陽遇陽得敵。不能行。故利用恆。恆久也常也。言潛龍勿用。守常不變也。守常不動。故無咎。陽遇陽行難。需而不進。故象曰不犯難行。大畜初九曰。有厲利己。厲與難皆指二三。此與鼎九二慎所之。大有初九曰無交。大壯初九曰徵兇。夬初九曰往不勝。姤九三曰其行次且。皆因陽遇陽。乃二千年說者。皆以需坎為難。謂初不取四。為不犯難。豈知難為二三。二三皆陽。陽遇陽行難。故不取四而用恆。非以坎為難而不取也。故夫同性相敵。異性相感之理不明。則易本立失。此不犯難及有厲利己等辭。所以永不得解也。</p><h3 id="象曰。需於郊。不犯難行也。利用恆無咎。未失常也。" tabindex="-1">象曰。需於郊。不犯難行也。利用恆無咎。未失常也。 <a class="header-anchor" href="#象曰。需於郊。不犯難行也。利用恆無咎。未失常也。" aria-label="Permalink to “象曰。需於郊。不犯難行也。利用恆無咎。未失常也。”">​</a></h3><p>陽遇陽得敵需而不進。故曰不犯難行。難指二三。</p><p>九二。需於沙。小有言。終吉。</p><p>沙近水。二較初略進。故曰需於沙。二至四伏艮。艮為沙。有言者爭訟也。乾為言。見左傳。兌口亦為言。見易林。乃兌言向外。與乾言相背。故爭訟。夬四之聞言不信。即如此取象也。兌為小故小有言。有言不吉。然而吉者。象曰衍在中。以居沙衍之中也。穆天子傳。天子遂東征。南絕沙衍。蓋水中有沙曰衍。故曰衍在中。以象中位也。象曰。雖小有言。以吉終者。明有言本不吉。然而吉者。以得中位也。虞翻用半象。謂三四震象半見。為小有言。穿鑿之說也。凡易雲有言。及聞言不信。有言不信者。皆爭訟也。非言之有無也。左傳昭五年。以謙為饞。首發其義。焦氏易林。暢述其旨。於是二千年有言誤解。盡行暴露。與利涉大川同。說詳焦氏易詁中。</p><h3 id="象曰。需於沙。衍在中也。雖小有言。以吉終也。" tabindex="-1">象曰。需於沙。衍在中也。雖小有言。以吉終也。 <a class="header-anchor" href="#象曰。需於沙。衍在中也。雖小有言。以吉終也。" aria-label="Permalink to “象曰。需於沙。衍在中也。雖小有言。以吉終也。”">​</a></h3><p>解見前。</p><p>九三。需於泥。致寇至。</p><p>震九四雲。震隊泥。以坎為泥也。九三去險益近。故曰需於泥。坎為寇。三近坎。故曰致寇至。</p><h3 id="象曰。需於泥。災在外也。自我致寇。敬慎不敗也。" tabindex="-1">象曰。需於泥。災在外也。自我致寇。敬慎不敗也。 <a class="header-anchor" href="#象曰。需於泥。災在外也。自我致寇。敬慎不敗也。" aria-label="Permalink to “象曰。需於泥。災在外也。自我致寇。敬慎不敗也。”">​</a></h3><p>坎為災。災在外。明尚未罹災。致寇至。明寇尚未至也。致之故在我。我能敬慎。則不至矣。不至則不敗。乾為惕。故曰敬慎。</p><p>六四。需於血。出自穴。</p><p>血。洫之省字。古文如此者。不可勝數。且溝洫亦坎象也。諸家以坎有血象。便作需於血。不辭甚矣。兌為穴。易林乾之鹹雲。反得丹穴。豫之兌雲。秋蛇向穴。皆以兌為穴。言四之所處。前臨溝洫。故曰需於洫。而居兌穴之上。故曰出自穴。毛奇齡惠棟焦循等。皆以坎為穴。用象既誤。故於出義不合也。(祇姚配中詁出字得解。)</p><h3 id="象曰。需於血。順以聽也。" tabindex="-1">象曰。需於血。順以聽也。 <a class="header-anchor" href="#象曰。需於血。順以聽也。" aria-label="Permalink to “象曰。需於血。順以聽也。”">​</a></h3><p>四陰宜順五陽。坎為耳。故曰聽。聽從也。</p><p>九五。需於酒食。貞吉。</p><p>坎為酒。食。實也。頤自求口實。鄭作食。是食實可通用。坎中實。故坎為食。易林履之蹇雲。天下饒食。謙之坎。食非其任。皆以坎為食。酒食在上。兌口承之。故曰需於酒食。貞吉者。卜問吉也。</p><h3 id="象曰。需於酒食。以中正也。" tabindex="-1">象曰。需於酒食。以中正也。 <a class="header-anchor" href="#象曰。需於酒食。以中正也。" aria-label="Permalink to “象曰。需於酒食。以中正也。”">​</a></h3><p>五位中正。釋貞吉之故也。</p><p>上六。入於穴。有不速之客。三人來。敬之。終吉。</p><p>互兌為穴。上來應三。則入於兌穴矣。而陽必上升。故曰不速之客。馬雲。速召也。乾為人。上應在三。故曰三人來。坎為畏懼。故曰敬之。言陰宜順陽也。上居卦終。故曰終吉。</p><h3 id="象曰。不速之客來。敬之終吉。雖不當位。未大失也。" tabindex="-1">象曰。不速之客來。敬之終吉。雖不當位。未大失也。 <a class="header-anchor" href="#象曰。不速之客來。敬之終吉。雖不當位。未大失也。" aria-label="Permalink to “象曰。不速之客來。敬之終吉。雖不當位。未大失也。”">​</a></h3><p>象明曰不速之客來。來而不當位。言三升上。不當位也。非謂上六本不當位。王弼不明升降之理。便謂初上無位。真妄說也。苟爽雲。上退居三。雖不當位。承陽有實。故未大失。固的解也。</p>',30)])])}const m=e(s,[["render",t]]);export{_ as __pageData,m as default};
